// Overture Maps POI index — a local business directory so searches don't
// depend on OSM/TomTom coverage. Lazy-loaded like the scan index; the service
// worker caches it on first fetch. Generated by scripts/build-places-index.
import { distance, type Place } from "./core";
import { nameScore } from "./suggestions";

type Row = { n: string; a?: string; la: number; lo: number; lw?: string };
let rows: Row[] | null = null;
let loading: Promise<Row[] | null> | null = null;

export function loadPlaces(): Promise<Row[] | null> {
  if (rows) return Promise.resolve(rows);
  if (!loading)
    loading = fetch("places/oc.json")
      .then((r) => (r.ok ? r.json() : null))
      .then((d: Row[] | null) => {
        for (const r of d || []) r.lw = r.n.toLowerCase();
        return (rows = d);
      })
      .catch(() => null);
  return loading;
}

// synchronous once loaded — callers should kick loadPlaces() first/early
export function searchPlaces(
  query: string,
  origin: { lat: number; lon: number },
  limit = 8,
): Place[] {
  if (!rows) {
    loadPlaces();
    return [];
  }
  const words = query
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((w) => w);
  if (!words.length) return [];
  const key = words.find((w) => w.length >= 4) ?? words[0];
  const scored: { p: Row; s: number }[] = [];
  for (const p of rows) {
    if (!p.lw!.includes(key)) continue;
    const s = nameScore(query, p.n);
    if (s >= 200) scored.push({ p, s });
  }
  const pt = (r: Row): Place => ({
    id: `ovt-${r.la},${r.lo}`,
    name: r.n,
    address: r.a,
    lat: r.la,
    lon: r.lo,
  });
  return scored
    .sort(
      (a, b) =>
        b.s - a.s || distance(origin, pt(a.p)) - distance(origin, pt(b.p)),
    )
    .slice(0, limit)
    .map((x) => pt(x.p));
}
